html:
{%- set items_per_page = 5 -%}
{%- set total_items = doc.items | length -%}
{%- set total_pages = ((total_items - 1) // items_per_page + 1) if total_items > 0 else 1 -%}
{%- set gross = doc.total -%}
{%- set disc  = doc.discount_amount or 0 -%}
{%- set after_disc = gross - disc -%}
{%- set deposit = doc.advance_paid or 0 -%}
{%- set after_dep = after_disc - deposit -%}
{%- set vat_amt = doc.total_taxes_and_charges or 0 -%}
{%- set grand  = doc.grand_total -%}

{%- for page_num in range(total_pages) -%}
{%- set page_start = page_num * items_per_page -%}
{%- set page_end = page_start + items_per_page -%}
{%- set is_last_page = (page_num == total_pages - 1) -%}

<div class="page">
  <div class="f company-address medium">
      {{ (doc.get("company_address_display") or "") }}
  </div>
  <div class="f customer"> {{ doc.customer }}</div>
  <div class="f customer-name">{{ doc.customer_name }}</div>
  <div class="f customer-address">
    {%- if doc.address_display -%}
      {{ doc.address_display }}
    {%- endif -%}
  </div>
  <div class="f phone">
    {%- if doc.contact_mobile or doc.contact_phone -%}
      โทร. {{ doc.contact_mobile or doc.contact_phone }}
    {%- endif -%}
  </div>
  <div class="f reference">
    {%- if doc.po_no -%}อ้างอิง {{ doc.po_no }}{%- endif -%}
  </div>
  <div class="f doc-no">{{ doc.name }}</div>
  <div class="f doc-date">{{ frappe.format_date(doc.posting_date, "dd/MM/yyyy") }}</div>
  <div class="f credit-days">
    {%- if doc.payment_schedule and doc.payment_schedule[0] -%}

        {%- set ps = doc.payment_schedule[0] -%}

        {{ ps.credit_days
            if ps.credit_days
            else frappe.utils.date_diff(doc.due_date, doc.posting_date)
        }}

    {%- elif doc.due_date and doc.posting_date -%}

        {{ frappe.utils.date_diff(doc.due_date, doc.posting_date) }}

    {%- endif -%}
  </div>
  <div class="f due-date">
    {%- if doc.payment_schedule and doc.payment_schedule[0] -%}
      {{ frappe.format_date(doc.payment_schedule[0].due_date, "dd/MM/yyyy") }}
    {%- elif doc.due_date -%}
      {{ frappe.format_date(doc.due_date, "dd/MM/yyyy") }}
    {%- endif -%}
  </div>
  <div class="f sales-order-no">{{ doc.po_no or "" }}</div>
  <div class="f sales-person">
    {%- for st in doc.sales_team -%}
      {{ st.sales_person }}{% if not loop.last %}, {% endif %}
    {%- endfor -%}
  </div>
  <div class="f territory">{{ doc.territory or "" }}</div>

  <div class="f items">
    <table>
      {%- for item in doc.items[page_start:page_end] -%}
      <tr>
        <td class="col-no">{{ page_start + loop.index }}</td>
        <td class="col-desc">
          <strong>{{ item.item_code }}</strong>
          {%- if item.item_name and item.item_name != item.item_code %} – {{ item.item_name }}{%- endif -%}
          {%- if item.description and item.description != item.item_name %}
            <br><span style="color:#444;font-size:7.5pt;">{{ item.description | striptags }}</span>
          {%- endif %}
        </td>
        <td class="col-qty">{{ item.qty | int if item.qty == item.qty | int else item.qty }} {{ item.uom }}</td>
        <td class="col-rate">{{ "{:,.2f}".format(item.rate) }}</td>
        <td class="col-amount">{{ "{:,.2f}".format(item.amount) }}</td>
      </tr>
      {%- endfor -%}
    </table>
  </div>

  <div class="f total">{{ "{:,.2f}".format(gross) }}</div>
  <div class="f discount">{{ "{:,.2f}".format(disc) if disc else "-" }}</div>
  <div class="f after-discount">{{ "{:,.2f}".format(after_disc) }}</div>
  <div class="f deposit">{{ "{:,.2f}".format(deposit) if deposit else "-" }}</div>
  <div class="f after-deposit">{{ "{:,.2f}".format(after_dep) }}</div>
  <div class="f vat-rate">
    {{ (doc.taxes[0].rate if doc.taxes and doc.taxes[0].rate else 0) }} %
  </div>
  <div class="f vat">{{ "{:,.2f}".format(vat_amt) }}</div>
  <div class="f grand">{{ "{:,.2f}".format(grand) }}</div>
  <div class="f amount-words">
    ({{ number_to_thai_currency(doc.grand_total, doc.currency) }}).
  </div>
  <div class="f terms">
      {{ doc.terms }}
  </div>

  <div class="f company">
      {{ doc.company }}
  </div>
</div>
{%- endfor -%}
